  startMission(name) {
    const m = this.game.missions;
    if (!m) return null;
    if (typeof m.start === 'function') return m.start(name);
    if (typeof m.activate === 'function') return m.activate(name);
    if (typeof m.setActive === 'function') return m.setActive(name);
