  objectivePosition() {
    const m = this.game.missions;
    if (!m) return null;
    const obj = m.objective || m.currentObjective || (m.current && m.current.objective);
    if (!obj) return null;
    const p = obj.position || (obj.marker && obj.marker.position) || obj;
